#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with default
# options (version latest, components empty).
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib

readonly INITIALIZE="/usr/local/share/gcloud-cli-feature/initialize"
readonly STATE_DIR="/var/lib/gcloud-cli"
readonly APT_FINGERPRINT="35BAA0B33E9EB396F59CA838C0BA5CE6DC6315A3"
readonly DNF_FINGERPRINT="C5F744A098136F40C370E8493156C631B64936F9"

detect_route() {
  local os_id os_like entry
  # shellcheck source=/dev/null
  os_id="$(. /etc/os-release && printf '%s\n' "${ID:-}")"
  # shellcheck source=/dev/null
  os_like="$(. /etc/os-release && printf '%s\n' "${ID_LIKE:-}")"
  for entry in ${os_id} ${os_like}; do
    case "${entry}" in
      debian | ubuntu)
        if command -v apt-get >/dev/null 2>&1; then
          echo apt
          return
        fi
        ;;
      fedora | rhel)
        if command -v dnf >/dev/null 2>&1; then
          echo dnf
          return
        fi
        ;;
    esac
  done
  echo fallback
}

route="$(detect_route)"

default_path() {
  local p cmd_path="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
  for cmd in gcloud bq gsutil; do
    p="$(env -i PATH="${cmd_path}" sh -c "command -v ${cmd}")" || return 1
    [[ -x "${p}" && "$(readlink -f "${p}")" != "${STATE_DIR}"* ]] || return 1
  done
}

profiles_untouched() {
  ! grep -qsE 'google-cloud-sdk|path\.bash\.inc|completion\.bash\.inc' "${HOME}/.bashrc" "${HOME}/.profile" 2>/dev/null
}

repo_and_key_configured() {
  local home records primaries fingerprint ok=1
  home="$(mktemp -d)"
  case "${route}" in
    apt)
      if [[ -f /etc/apt/sources.list.d/google-cloud-sdk.list ]] \
        && grep -qxF \
          'deb [signed-by=/usr/share/keyrings/cloud.google.gpg] https://packages.cloud.google.com/apt cloud-sdk main' \
          /etc/apt/sources.list.d/google-cloud-sdk.list; then
        records="$(
          GNUPGHOME="${home}" gpg --batch --show-keys --with-colons /usr/share/keyrings/cloud.google.gpg 2>/dev/null
        )"
        primaries="$(grep -cE '^(pub|sec):' <<<"${records}" || true)"
        fingerprint="$(awk -F: '$1 == "pub" { p = 1; next } p && $1 == "fpr" { print $10; exit }' <<<"${records}")"
        if ((primaries == 1)) && [[ "${fingerprint}" == "${APT_FINGERPRINT}" ]]; then ok=0; fi
      fi
      ;;
    dnf)
      if [[ -f /etc/yum.repos.d/google-cloud-sdk.repo ]] \
        && grep -q '^gpgcheck=1$' /etc/yum.repos.d/google-cloud-sdk.repo \
        && grep -q '^repo_gpgcheck=0$' /etc/yum.repos.d/google-cloud-sdk.repo \
        && grep -q '^baseurl=https://packages\.cloud\.google\.com/yum/repos/cloud-sdk-el10-' \
          /etc/yum.repos.d/google-cloud-sdk.repo; then
        records="$(
          GNUPGHOME="${home}" gpg --batch --show-keys --with-colons \
            /etc/pki/rpm-gpg/RPM-GPG-KEY-google-cloud-rpm-v10 2>/dev/null
        )"
        primaries="$(grep -cE '^(pub|sec):' <<<"${records}" || true)"
        fingerprint="$(awk -F: '$1 == "pub" { p = 1; next } p && $1 == "fpr" { print $10; exit }' <<<"${records}")"
        if ((primaries == 1)) && [[ "${fingerprint}" == "${DNF_FINGERPRINT}" ]]; then ok=0; fi
      fi
      ;;
    fallback)
      if [[ -x /usr/local/share/google-cloud-sdk/bin/gcloud ]]; then ok=0; fi
      ;;
  esac
  rm -rf "${home}"
  return "${ok}"
}

caches_clean() {
  local leftover=""
  case "${route}" in
    apt)
      leftover="$(find /var/lib/apt/lists -maxdepth 1 -mindepth 1 2>/dev/null || true)"
      [[ -z "${leftover}" ]]
      ;;
    dnf)
      leftover="$(find /var/cache/dnf /var/cache/libdnf5 -name '*.rpm' -o -name 'repomd.xml' 2>/dev/null || true)"
      [[ -z "${leftover}" ]]
      ;;
    fallback)
      if command -v zypper >/dev/null 2>&1; then
        leftover="$(find /var/cache/zypp -name '*.rpm' -o -name 'repomd.xml' 2>/dev/null || true)"
        [[ -z "${leftover}" ]]
      fi
      ;;
  esac
}

no_temp_residue() {
  ! compgen -G '/tmp/gcloud-cli-gnupg.*' >/dev/null \
    && ! compgen -G '/tmp/gcloud-cli-build.*' >/dev/null \
    && ! compgen -G '/usr/local/share/.gcloud-cli-install.*' >/dev/null
}

links_to() {
  [[ -L "$1" && "$(readlink -f "$1")" == "$2" ]]
}

no_credential_files() {
  ! test -e "${STATE_DIR}/config/credentials.db" \
    && ! test -e "${STATE_DIR}/config/access_tokens.db" \
    && ! test -e "${STATE_DIR}/config/application_default_credentials.json"
}

check "gcloud runs as the remote user" gcloud version
check "bq runs as the remote user" bq version
check "gsutil runs as the remote user" gsutil version
check "gcloud, bq, and gsutil resolve on default PATH outside state volume" default_path
check "shell profiles remain untouched" profiles_untouched
check "route (${route}) repository or archive and pinned key are configured" repo_and_key_configured
check "package-manager caches are clean" caches_clean
check "no temporary GnuPG or staging directories remain" no_temp_residue
check "creation-time initialization succeeds without credentials" "${INITIALIZE}"
check "user .config/gcloud links into the state volume" links_to "${HOME}/.config/gcloud" "${STATE_DIR}/config"
check "user .config itself is not linked" test ! -L "${HOME}/.config"
check "the state root belongs privately to the remote user" \
  test "$(stat -c %u:%a "${STATE_DIR}")" = "$(id -u):700"
check "no credential files exist after build" no_credential_files

reportResults
